import { Button } from "@/components/ui/button";
import { Field, FieldDescription, FieldLabel } from "@/components/ui/field";
import { errorMessage } from "@/lib/errors";

export type Region = "us" | "eu" | "au" | "ca";

const REGIONS: Array<{ value: Region; label: string }> = [
  { value: "us", label: "United States" },
  { value: "eu", label: "Europe (Ireland)" },
  { value: "au", label: "Australia (Sydney)" },
  { value: "ca", label: "Canada (Central)" },
];

export function RegionForm({ region }: { region: Region }) {
  const update = useMutation(api.users.updateSettings);
  const [value, setValue] = useState<Region>(region);
  const [saving, setSaving] = useState(false);

  async function save() {
    setSaving(true);
    try {
      await update({ region: value });
      toast.success("Region saved");
    } catch (e) {
      toast.error(errorMessage(e));
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="space-y-6">
      <Field>
        <FieldLabel htmlFor="region">Data region</FieldLabel>
        <select
          id="region"
          className="h-9 rounded-md border bg-background px-3 text-sm"
          value={value}
          onChange={(e) => setValue(e.target.value as Region)}
        >
          {REGIONS.map((r) => (
            <option key={r.value} value={r.value}>
              {r.label}
            </option>
          ))}
        </select>
        <FieldDescription>
          Where new experiences are stored. Existing ones stay where they were created.
          Defaults to the United States.
        </FieldDescription>
      </Field>
      <Button onClick={() => void save()} disabled={saving || value === region}>
        Save changes
      </Button>
    </div>
  );
}
