          )}
        </form.Field>
      </FieldGroup>
      <div className="flex gap-2">
        <Button type="submit" disabled={form.state.isSubmitting || uploading}>
          {moment ? "Save moment" : "Add moment"}
        </Button>
        {moment && (
          <Button type="button" variant="ghost" onClick={onDone}>
            Cancel
          </Button>
        )}
      </div>
    </form>
  );
}
